prompt.text:
Repair the CommonJS module below and return a corrected complete source file exporting exactly `{ advanceCursor }`.

`advanceCursor(state)` moves a cursor once on a rectangular zero-indexed board. `state` must be a non-null, non-array object containing positive integer `width` and `height`; a `cursor` object with integer in-bounds `x` and `y`; a `direction` object whose integer `x` and `y` form exactly one of `(1,0)`, `(-1,0)`, `(0,1)`, or `(0,-1)`; and an `obstacles` array of objects with integer in-bounds `x` and `y`. Malformed state must throw `TypeError`.

If the destination is outside `0 <= x < width` and `0 <= y < height`, return `{ moved: false, reason: "boundary", state }`. If any obstacle occupies the destination, return `{ moved: false, reason: "obstacle", state }`; the first-to-last obstacle order is used only for checking and is otherwise preserved. On success, return `{ moved: true, reason: null, state: nextState }`, where `nextState` is a new object with a new cursor and all unrelated properties preserved. On either failure return the original state reference. Never mutate any input or reorder obstacles. Moving onto the last valid column or row is allowed; moving to a coordinate equal to width or height is not.

Known-bad source:

```javascript
'use strict';

function advanceCursor(state) {
  const validPoint = (point) => point !== null && typeof point === 'object' &&
    Number.isInteger(point.x) && Number.isInteger(point.y);
  const validDirection = (direction) => validPoint(direction) &&
    Math.abs(direction.x) + Math.abs(direction.y) === 1;

  if (state === null || typeof state !== 'object' || Array.isArray(state) ||
      !Number.isInteger(state.width) || state.width <= 0 ||
      !Number.isInteger(state.height) || state.height <= 0 ||
      !validPoint(state.cursor) || state.cursor.x < 0 || state.cursor.x >= state.width ||
      state.cursor.y < 0 || state.cursor.y >= state.height ||
      !validDirection(state.direction) || !Array.isArray(state.obstacles) ||
      !state.obstacles.every((point) => validPoint(point) && point.x >= 0 &&
        point.x < state.width && point.y >= 0 && point.y < state.height)) {
    throw new TypeError('invalid state');
  }

  const destination = {
    x: state.cursor.x + state.direction.x,
    y: state.cursor.y + state.direction.y
  };

  if (destination.x < 0 || destination.x > state.width ||
      destination.y < 0 || destination.y > state.height) {
    return { moved: false, reason: 'boundary', state };
  }
  if (state.obstacles.some((point) => point.x === destination.x && point.y === destination.y)) {
    return { moved: false, reason: 'obstacle', state };
  }

  return {
    moved: true,
    reason: null,
    state: { ...state, cursor: destination }
  };
}

module.exports = { advanceCursor };
```

