'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['advanceCursor']);
assert.strictEqual(typeof api.advanceCursor, 'function');
const { advanceCursor } = api;

const state = {
  width: 3,
  height: 2,
  cursor: { x: 1, y: 0 },
  direction: { x: 1, y: 0 },
  obstacles: [{ x: 0, y: 1 }],
  label: 'board'
};
const moved = advanceCursor(state);
assert.strictEqual(moved.moved, true);
assert.strictEqual(moved.reason, null);
assert.notStrictEqual(moved.state, state);
assert.deepStrictEqual(moved.state, {
  width: 3,
  height: 2,
  cursor: { x: 2, y: 0 },
  direction: state.direction,
  obstacles: state.obstacles,
  label: 'board'
});
assert.notStrictEqual(moved.state.cursor, state.cursor);
assert.strictEqual(moved.state.direction, state.direction);
assert.strictEqual(moved.state.obstacles, state.obstacles);
assert.deepStrictEqual(state.cursor, { x: 1, y: 0 });

const rightBoundary = {
  width: 3,
  height: 2,
  cursor: { x: 2, y: 0 },
  direction: { x: 1, y: 0 },
  obstacles: []
};
let result = advanceCursor(rightBoundary);
assert.deepStrictEqual(result, { moved: false, reason: 'boundary', state: rightBoundary });
assert.strictEqual(result.state, rightBoundary);

const bottomBoundary = {
  width: 2,
  height: 2,
  cursor: { x: 0, y: 1 },
  direction: { x: 0, y: 1 },
  obstacles: []
};
result = advanceCursor(bottomBoundary);
assert.strictEqual(result.moved, false);
assert.strictEqual(result.reason, 'boundary');
assert.strictEqual(result.state, bottomBoundary);

const leftBoundary = {
  width: 2,
  height: 2,
  cursor: { x: 0, y: 0 },
  direction: { x: -1, y: 0 },
  obstacles: []
};
assert.strictEqual(advanceCursor(leftBoundary).reason, 'boundary');

const obstacle1 = { x: 1, y: 0 };
const obstacle2 = { x: 1, y: 1 };
const blocked = {
  width: 2,
  height: 2,
  cursor: { x: 0, y: 0 },
  direction: { x: 1, y: 0 },
  obstacles: [obstacle1, obstacle2],
  extra: true
};
result = advanceCursor(blocked);
assert.deepStrictEqual(result, { moved: false, reason: 'obstacle', state: blocked });
assert.strictEqual(result.state, blocked);
assert.strictEqual(blocked.obstacles[0], obstacle1);
assert.strictEqual(blocked.obstacles[1], obstacle2);

for (const invalid of [
  null,
  [],
  {},
  { width: 0, height: 1, cursor: { x: 0, y: 0 }, direction: { x: 1, y: 0 }, obstacles: [] },
  { width: 1.5, height: 1, cursor: { x: 0, y: 0 }, direction: { x: 1, y: 0 }, obstacles: [] },
  { width: 1, height: -1, cursor: { x: 0, y: 0 }, direction: { x: 1, y: 0 }, obstacles: [] },
  { width: 2, height: 2, cursor: { x: 2, y: 0 }, direction: { x: -1, y: 0 }, obstacles: [] },
  { width: 2, height: 2, cursor: { x: 0.5, y: 0 }, direction: { x: 1, y: 0 }, obstacles: [] },
  { width: 2, height: 2, cursor: { x: 0, y: 0 }, direction: { x: 1, y: 1 }, obstacles: [] },
  { width: 2, height: 2, cursor: { x: 0, y: 0 }, direction: { x: 0, y: 0 }, obstacles: [] },
  { width: 2, height: 2, cursor: { x: 0, y: 0 }, direction: { x: 2, y: 0 }, obstacles: [] },
  { width: 2, height: 2, cursor: { x: 0, y: 0 }, direction: { x: 1, y: 0 }, obstacles: null },
  { width: 2, height: 2, cursor: { x: 0, y: 0 }, direction: { x: 1, y: 0 }, obstacles: [{ x: 2, y: 0 }] },
  { width: 2, height: 2, cursor: { x: 0, y: 0 }, direction: { x: 1, y: 0 }, obstacles: [{ x: 1.2, y: 0 }] }
]) {
  assert.throws(() => advanceCursor(invalid), TypeError);
}

